#pragma once
#include "electrothermal_model.hpp"
namespace electrothermal::qualification {
using Poly=std::vector<Quadratic2>;
inline constexpr std::array<const char*,4> names{"voltage","current","temperature_rise","stored_energy"};
inline constexpr std::array<const char*,4> units{"V","A","K_rise","J"};
inline constexpr std::array<double,4> tolerances{.01,.01,.02,.05};
struct Node {Mat<2,2> F{},U{};};
inline std::vector<Node> coefficients(const System<3,2>& sys){auto a=sys.forward({1.,0.}),b=sys.forward({0.,1.}),ab=sys.forward({1.,1.});std::vector<Node> n(a.state.size());for(std::size_t j=0;j<n.size();++j){n[j].F={{{a.state[j][0],b.state[j][0]},{a.state[j][1],b.state[j][1]}}};double cross=.5*(ab.state[j][2]-a.state[j][2]-b.state[j][2]);n[j].U={{{a.state[j][2],cross},{cross,b.state[j][2]}}};}return n;}
inline Quadratic2 linear(Vec<2> a){return {0.,a,{}};}
inline Quadratic2 quadratic(Mat<2,2> a){return {0.,{},a};}
inline std::array<Vec<2>,3> electrical_polynomial(const Node& a,const Node& b,double h,int row){auto slope=h*mv(transpose(a.F),A[row]);return {a.F[row],slope,b.F[row]-a.F[row]-slope};}
inline Poly temperature_polynomial(const Node& a,const Node& b,double h){auto slope=scaled(h,add(scaled(beta,outer(a.F[1],a.F[1])),scaled(-decay,a.U)));return {quadratic(a.U),quadratic(slope),quadratic(add(add(b.U,scaled(-1.,a.U)),scaled(-1.,slope)))};}
inline Poly goal_polynomial(const Node& a,const Node& b,double h,int goal){if(goal<2){auto c=electrical_polynomial(a,b,h,goal);return {linear(c[0]),linear(c[1]),linear(c[2])};}if(goal==2)return temperature_polynomial(a,b,h);Poly p(5);for(int row=0;row<2;++row){auto c=electrical_polynomial(a,b,h,row);for(int j=0;j<3;++j)for(int k=0;k<3;++k)p[j+k]=p[j+k]+quadratic(scaled(.5*(row==0?C:L),outer(c[j],c[k])));}return p;}
inline Quadratic2 node_goal(const Node& n,int goal){if(goal<2)return linear(n.F[goal]);if(goal==2)return quadratic(n.U);return quadratic(add(scaled(.5*C,outer(n.F[0],n.F[0])),scaled(.5*L,outer(n.F[1],n.F[1]))));}
struct Errors {std::vector<double> electrical,thermal;std::vector<double> max_electrical;};
inline Errors allowance(const System<3,2>& sys,const std::vector<Node>& nodes){auto& g=sys.grid();Errors E;E.electrical.resize(nodes.size());E.thermal.resize(nodes.size());E.max_electrical.resize(g.steps());std::array<Vec<2>,4> corners{{prior.lower,{prior.upper[0],prior.lower[1]},prior.upper,{prior.lower[0],prior.upper[1]}}};
 for(std::size_t n=0;n<g.steps();++n){double h=g.time[n+1]-g.time[n],D=0.;for(auto corner:corners)D=std::max(D,linear_theta_quadratic_defect_bound(A,mv(nodes[n].F,corner),mv(nodes[n+1].F,corner),h,g.theta[n],[](auto v){return std::hypot(v[0],v[1]);}));E.electrical[n+1]=propagate_defect_bound(E.electrical[n],D,h,0.);
  auto u=temperature_polynomial(nodes[n],nodes[n+1],h);auto i=electrical_polynomial(nodes[n],nodes[n+1],h,1);Poly residual(5);for(int j=0;j<3;++j)residual[j]=residual[j]+decay*u[j];residual[0]=residual[0]+(1/h)*u[1];residual[1]=residual[1]+(2/h)*u[2];for(int j=0;j<3;++j)for(int k=0;k<3;++k)residual[j+k]=residual[j+k]+quadratic(scaled(-beta,outer(i[j],i[k])));double thermal_defect=0.;for(auto q:residual)thermal_defect+=absolute_bound(quadratic_range(q,prior));
  double imax=0.;for(auto row:i)imax+=absolute_bound(quadratic_range(linear(row),prior));double em=E.electrical[n+1];double forcing=thermal_defect+beta*em*(2*imax+em);E.thermal[n+1]=propagate_defect_bound(E.thermal[n],forcing,h,-decay);
  double vmax=0.;for(auto row:electrical_polynomial(nodes[n],nodes[n+1],h,0))vmax+=absolute_bound(quadratic_range(linear(row),prior));E.max_electrical[n]=std::hypot(vmax,imax);
 }return E;}
inline BoxCover2 feasible_cover(const System<3,2>& sys,const std::vector<Node>& n,const Errors& E,int design,bool analytical=false){struct Strip {Quadratic2 q;double lo,hi;};std::vector<Strip> strips;for(auto o:observations(design)){auto j=node_at(sys.grid(),o.tau);auto q=o.component==2?quadratic(analytical?temperature_matrix(o.tau):n[j].U):linear(analytical?propagator(o.tau)[0]:n[j].F[0]);double width=o.scale+(analytical?0.:(o.component==2?E.thermal[j]:E.electrical[j]));strips.push_back({q,o.value-width,o.value+width});}return subdivide_feasible_boxes(prior,{.003125,.002734375},[&](const Box2& b){for(auto strip:strips){auto r=quadratic_range(strip.q,b);if(r.upper<strip.lo||r.lower>strip.hi)return false;}return true;},500000);}
struct Result {Vec<2> center{};BoxCover2 cover,reference;Errors error;std::vector<std::array<double,4>> whole,local;IntervalQualification<4> decision,local_decision;std::size_t positive{},negative{},unresolved{};};
template<class Check> Result experiment(const System<3,2>& sys,int design,Check&& check){Result r;r.center=fit(sys,{1.1,.6}).control;auto n=coefficients(sys);r.error=allowance(sys,n);r.cover=feasible_cover(sys,n,r.error,design);r.reference=feasible_cover(sys,n,r.error,design,true);check("numerical global cover resolves requested boxes",r.cover.resolution_complete?0.:1.,0.);check("analytical global cover resolves requested boxes",r.reference.resolution_complete?0.:1.,0.);check("cover contains physical truth",cover_contains(r.cover,truth)?0.:1.,0.);for(auto b:r.cover.boxes){if(b.lower[0]>0)++r.positive;else if(b.upper[0]<0)++r.negative;else ++r.unresolved;}
 if(design!=1)check("opposite physical truth remains feasible",cover_contains(r.cover,-1.*truth)?0.:1.,0.);else check("informative signed datum excludes opposite truth",cover_contains(r.cover,-1.*truth)?1.:0.,0.);
 double error_violation=0.,representation=0.;for(auto corner:std::array<Vec<2>,5>{prior.lower,prior.upper,Vec<2>{prior.lower[0],prior.upper[1]},Vec<2>{prior.upper[0],prior.lower[1]},probe}){auto tr=sys.forward(corner);for(std::size_t j=0;j<n.size();++j){auto e=mv(n[j].F,corner);representation=std::max(representation,norm(tr.state[j]-Vec<3>{e[0],e[1],dot(corner,mv(n[j].U,corner))}));}for(std::size_t j=0;j<sys.grid().steps();++j){double h=sys.grid().time[j+1]-sys.grid().time[j];for(double s:{0.,.5,1.}){auto exact_state=exact(sys.grid().time[j]-t0+s*h,corner);std::array<double,3> approx{};for(int k=0;k<3;++k){auto p=goal_polynomial(n[j],n[j+1],h,k);double power=1.;for(auto q:p){approx[k]+=power*evaluate(q,corner);power*=s;}}error_violation=std::max({error_violation,std::hypot(exact_state[0]-approx[0],exact_state[1]-approx[1])-r.error.electrical[j+1],std::abs(exact_state[2]-approx[2])-std::max(r.error.thermal[j],r.error.thermal[j+1])});}}}
 check("discrete coefficient maps match nonlinear forward solves",representation,3e-11);check("computable defect allowance versus exact state probes",error_violation,3e-10);
 BoxCover2 selected;for(auto box:r.cover.boxes)if(box.lower[0]>0)selected.boxes.push_back(box);
 auto& g=sys.grid();r.whole.resize(g.steps());r.local.resize(g.steps());for(std::size_t j=0;j<g.steps();++j){double h=g.time[j+1]-g.time[j];for(int goal=0;goal<4;++goal){auto polynomial=goal_polynomial(n[j],n[j+1],h,goal);for(auto& q:polynomial)q.constant-=evaluate(q,r.center);double bound=absolute_bound(cover_polynomial_quadratic_range(r.cover,polynomial)),local=absolute_bound(cover_polynomial_quadratic_range(selected,polynomial));double e=goal<2?r.error.electrical[j+1]:goal==2?std::max(r.error.thermal[j],r.error.thermal[j+1]):r.error.max_electrical[j]*r.error.electrical[j+1]+.5*r.error.electrical[j+1]*r.error.electrical[j+1];r.whole[j][goal]=bound+e;r.local[j][goal]=local+e;}}
 std::vector<double> times;for(auto t:g.time)times.push_back(t-t0);r.decision=qualify_intervals(times,r.whole,tolerances);r.local_decision=qualify_intervals(times,r.local,tolerances);check("global cover has no unresolved sign-crossing boxes",r.unresolved,0.);
 std::size_t feasible_probes=0;double missed=0.;for(auto box:r.reference.boxes){Vec<2> point{.5*(box.lower[0]+box.upper[0]),.5*(box.lower[1]+box.upper[1])};bool feasible=true;for(auto o:observations(design))if(std::abs(exact(o.tau,point)[o.component]-o.value)>o.scale)feasible=false;if(feasible){++feasible_probes;if(!cover_contains(r.cover,point))missed=1.;}}check("analytically feasible reference probes retained by numerical cover",missed,0.);check("nonempty analytical feasible probe population",feasible_probes>0?0.:1.,0.);
 double envelope_violation=0.;for(std::size_t j=0;j<g.steps();++j){double h=g.time[j+1]-g.time[j];for(double s:{0.,.5,1.}){std::array<double,4> center{};for(int k=0;k<4;++k){auto p=goal_polynomial(n[j],n[j+1],h,k);double power=1.;for(auto q:p){center[k]+=power*evaluate(q,r.center);power*=s;}}for(auto point:std::array<Vec<2>,2>{truth,design==1?truth:-1.*truth}){auto x=exact(times[j]+s*h,point);std::array<double,4> value{x[0],x[1],x[2],energy(x)};for(int k=0;k<4;++k)envelope_violation=std::max(envelope_violation,(std::abs(value[k]-center[k])-r.whole[j][k])/tolerances[k]);}}}check("physical envelopes enclose exact feasible branch witnesses",envelope_violation,3e-9);
 return r;}
}
